from pathlib import Path
from fontTools.pens.reverseContourPen import ReverseContourPen
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
from fontTools.svgLib.path import parse_path

OUT=Path(__file__).resolve().parent
D={}
def transform(path, matrix):
    p=SVGPathPen(None);parse_path(path,TransformPen(p,matrix));return p.getCommands()
def reverse(path):
    p=SVGPathPen(None);parse_path(path,ReverseContourPen(p));return p.getCommands()

def glyph(char, width, outline, *holes):
    paths=[outline]
    for hole in holes:
        p=SVGPathPen(None);parse_path(hole,ReverseContourPen(p));paths.append(p.getCommands())
    D[char]=(width,' '.join(paths))
def oval(cx,cy,rx,ry):
    k=.55228475
    return f'M{cx+rx} {cy} C{cx+rx} {cy+ry*k} {cx+rx*k} {cy+ry} {cx} {cy+ry} C{cx-rx*k} {cy+ry} {cx-rx} {cy+ry*k} {cx-rx} {cy} C{cx-rx} {cy-ry*k} {cx-rx*k} {cy-ry} {cx} {cy-ry} C{cx+rx*k} {cy-ry} {cx+rx} {cy-ry*k} {cx+rx} {cy} Z'
def ribbon(x1,y1,x2,y2,width):
    # Rounded filled strip, used for functional symbol strokes only.
    dx=x2-x1;dy=y2-y1;length=math.hypot(dx,dy);nx=-dy/length*width/2;ny=dx/length*width/2
    return f'M{x1+nx} {y1+ny} L{x2+nx} {y2+ny} Q{x2+nx+dx/length*width} {y2+ny+dy/length*width} {x2-nx} {y2-ny} L{x1-nx} {y1-ny} Q{x1-nx-dx/length*width} {y1-ny-dy/length*width} {x1+nx} {y1+ny} Z'

