template=(OUT/'font/glyph-template.svg').read_text();items=[]
for char,(width,path) in D.items():
    name=names.get(char,char if char.isalpha() else f'uni{ord(char):04X}')
    source=OUT/'drawings'/f'u{ord(char):04x}.svg'
    source.write_text(template.replace('<g id="glyph" fill="#000000"></g>',f'<g id="glyph" fill="#000000"><path d="{path}"/></g>'))
    items.append({'name':name,'svg_path':str(source),'codepoints':[f'U+{ord(char):04X}'],'advance_width':width})
(OUT/'extension-glyphs.json').write_text(json.dumps(items,indent=2))
print(f'Drew {len(items)} new encoded glyphs')
